using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Web;
using sv_81cab253d2554b68b3c72a9f28a6fee2.Client;

namespace sv_81cab253d2554b68b3c72a9f28a6fee2;

// Server-side AuthenticationStateProvider that returns a hardcoded user
// and persists the auth state into PersistentComponentState so the
// WebAssembly client can pick it up after the handoff.
public sealed class PersistingServerAuthenticationStateProvider : AuthenticationStateProvider, IDisposable
{
    private static readonly AuthenticationState _state = CreateState();
    private readonly PersistingComponentStateSubscription _subscription;

    public PersistingServerAuthenticationStateProvider(PersistentComponentState persistentComponentState)
    {
        _subscription = persistentComponentState.RegisterOnPersisting(() =>
        {
            var principal = _state.User;
            var userInfo = new UserInfo
            {
                Email = principal.FindFirstValue(ClaimTypes.Email) ?? principal.Identity?.Name ?? "",
                Roles = principal.FindAll(ClaimTypes.Role).Select(c => c.Value).ToArray(),
            };

            persistentComponentState.PersistAsJson(nameof(UserInfo), userInfo);
            return Task.CompletedTask;
        }, RenderMode.InteractiveWebAssembly);
    }

    private static AuthenticationState CreateState()
    {
        var claims = new[]
        {
            new Claim(ClaimTypes.Name, "bob@example.com"),
            new Claim(ClaimTypes.Email, "bob@example.com"),
            new Claim(ClaimTypes.Role, "User"),
            new Claim(ClaimTypes.Role, "Editor"),
        };

        var identity = new ClaimsIdentity(claims, authenticationType: "Hardcoded");
        return new AuthenticationState(new ClaimsPrincipal(identity));
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync() => Task.FromResult(_state);

    public void Dispose() => _subscription.Dispose();
}

